def d(label,fn,key,kp,variable='x',chain=False,domain='All real inputs where the original expression is defined and differentiable.'):
 p=v(label,f'diff({fn},{variable})',key,kp,'Read the ORIGINAL function and requested variable '+variable+'. '+('Select outer and inner functions and MULTIPLY both derivatives.'if chain else'Expand products or divide numerator terms by the original denominator,then differentiate each rational-power term. No product/quotient-rule requirement is inferred.')+' Keep named constants fixed and original domains. '+domain)
 p.update(assessed_8227_demand_ids=[CHAIN if chain else POWER],component_demand_ids=[POWER]if chain else[],original_function=fn,differentiation_variable=variable,real_domain=domain);return p
def gradient(label,fn,at,key,kp):
 p=v(label,f'diff({fn},x).subs(x,{at})',key,kp,'Differentiate the ORIGINAL function,then substitute the given xcoordinate. The ordinate is found from the original curve,not from its derivative. Check point membership separately before reusing a stated pair.')
 p.update(assessed_8227_demand_ids=[GRAD],component_demand_ids=[POWER],original_function=fn,source_x=at);return p

